    private void jButton2ActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jButton2ActionPerformed
        try{
            String sql= "SELECT * FROM login WHERE username=? and password=? and options=?" ;
            Connection conn = DriverManager.getConnection("jdbc:mysql://localhost/pet","root","");
            PreparedStatement pst = conn.prepareStatement(sql);
            pst.setString(1,username.getText());
            pst.setString(2, password.getText());
            pst.setString(3, String.valueOf(jComboBox1.getSelectedItem()));
            ResultSet rs;
            rs = pst.executeQuery();
            if (rs.next()){
                JOptionPane.showMessageDialog(null, "Welcome User");
                if (jComboBox1.getSelectedIndex()==1){
                    Managerpage M= new Managerpage();
                    M.setVisible(true);
                    this.setVisible(false);
                }
                else if (jComboBox1.getSelectedIndex()==0){
                    Dashboard c =new Dashboard();
                    c.setVisible(true);
                    this.setVisible(false);
                }
            }else{
                JOptionPane.showMessageDialog(null, "invild username and password");
            }
        }
        catch(Exception ex){
            JOptionPane.showMessageDialog(this,ex.getMessage());
        }
    }//GEN-LAST:event_jButton2ActionPerformed

